"""dataset.py -- 构建训练数据"""
import numpy as np
from features import seq_to_windowed_matrix

# SpCas9序列 (UniProt: Q99ZW2)
SPCAS9 = ""

# 已知SpCas9互作位点 (文献数据+PDB 4UN3)
# 每个位点 (起始位置, 结束位置, 描述)
INTERFACE_SITES = [
    (10, 10, "RuvC catalytic"),
    (71, 76, "sgRNA contact"),
    (165, 169, "sgRNA contact"),
    (403, 410, "DNA recognition"),
    (445, 450, "target DNA"),
    (585, 590, "target DNA"),
    (656, 664, "target DNA"),
    (715, 720, "HNH linker"),
    (770, 775, "HNH nuclease"),
    (840, 840, "HNH catalytic"),
    (925, 930, "RuvC-III"),
    (1015, 1020, "sgRNA contact"),
    (1099, 1104, "PAM-interacting"),
    (1242, 1247, "PAM-interacting"),
    (1333, 1335, "PAM arginines"),
]

def build_training_set():
    """用SpCas9已知互作位点构建训练集"""
    seq = SPCAS9
    X = seq_to_windowed_matrix(seq)  # N×8
    n = len(seq)

    # 标签：默认全0
    y = np.zeros(n, dtype=int)

    # 标记互作位点
    for start, end, desc in INTERFACE_SITES:
        start -= 1   # 转0-index
        if end <= n:
            y[start:end] = 1

    return X, y, seq

if __name__ == "__main__":
    X, y, seq = build_training_set()
    print(f"序列长度: {len(seq)}")
    print(f"特征矩阵: {X.shape}")
    print(f"正样本(互作位点): {y.sum()} 个")
    print(f"负样本(非互作): {len(y) - y.sum()} 个")
